body:
And a quick snippet for anyone who stumbles on this and doesn't want to wait on the engine fix (or doesn't want to do a custom build):

```
using Godot;
using System.Collections.Generic;

/// <summary>
/// This is a(nother) potential fix to the `script.is_null()` issue (https://github.com/godotengine/godot/issues/109711)
/// Just set this as a global startup script on your project and it will prevent the scripts from ever being GC'd.
/// </summary>
/// <remarks>
/// Note, you need to be _very_ careful not to have stale `.cs.uid` files in your project folder for this to work correctly,
/// otherwise it'll try to load a no longer extant script and immediately crash.
/// I've included the method I used called `CleanupDanglingScriptUIDs`. Just call that from an `EditorPlugin` or something
/// and you're good.
/// </remarks>
[GlobalClass]
public partial class ScriptHoarder : Node {
	private List<CSharpScript> AllScripts;

	public override void _Ready() {
		base._Ready();
		AllScripts = new List<CSharpScript>();
		GatherScripts("res://", AllScripts);
	}

	public static void GatherScripts(string path, List<CSharpScript> result) {
		foreach (string entry in ResourceLoader.ListDirectory(path)) {
			string fullPath = path + entry;
			if (entry.EndsWith('/') && !entry.StartsWith('.')) {
				GatherScripts(fullPath, result);
			} else {
				if (fullPath.EndsWith(".cs")) {
					CSharpScript script = ResourceLoader.Load<CSharpScript>(fullPath);
					result.Add(script);
				}
			}
		}
	}

	public static void CleanupDanglingScriptUIDs() {
		CleanupDanglingResourceUIDsInternal("res://", false);
	}

	private static void CleanupDanglingScriptUIDs_Internal(string dirPath, bool dryRun = false) {
		if (!dirPath.EndsWith("/")) {
			dirPath += "/";
		}
		DirAccess directory = DirAccess.Open(dirPath);

		foreach (string file in directory.GetFiles()) {
			string fullFile = dirPath + file;
			if (file.EndsWith(".cs.uid") && !FileAccess.FileExists(fullFile.RightPartition(".uid").Item1)) {
				GD.Print($"Removing unused C# UID file {fullFile}");
				if (!dryRun) {
					directory.Remove(file);
				}
			}
		}

		foreach (string subdir in directory.GetDirectories()) {
			if (!subdir.StartsWith(".")) {
				CleanupDanglingResourceUIDsInternal(dirPath + subdir, dryRun);
			}
		}
	}
}
```
